from pathlib import Path

DASH=Path('js/modules/dashboard.js')
CSS=Path('css/design-system.css')
TEST=Path('tests/dashboard-card-routes-smoke.test.js')
SW=Path('service-worker.js')

dash=DASH.read_text(encoding='utf-8')
old="""function quickSection(){return section('Hızlı İşlemler','⚡','quick',`<div class=\"ka-home-quick\"><button type=\"button\" data-dash-route=\"academic\" data-dash-page=\"written\" data-dash-title=\"Yazılı Sınavlar\"><span>📝</span><b>Sınav Ekle</b></button><button type=\"button\" data-dash-quick-note><span>📒</span><b>Not Ekle</b></button><button type=\"button\" data-dash-route=\"communication\" data-dash-page=\"messages\" data-dash-title=\"Mesajlaşma\"><span>💬</span><b>Mesaj Gönder</b></button><button type=\"button\" data-dash-route=\"communication\" data-dash-page=\"announcements\" data-dash-title=\"Duyurular\"><span>📣</span><b>Duyurular</b></button></div>`) }"""
new="""function quickSection(){const exam='<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M9 11l3 3L22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg>',note='<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z\"/><path d=\"M14 2v6h6M8 13h8M8 17h6\"/></svg>',message='<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4v8Z\"/></svg>',megaphone='<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m3 11 18-5v12L3 14v-3Z\"/><path d=\"M11.6 16.5 13 21H7l-1.2-6\"/></svg>';return `<section class=\"kh-section\" data-home-section=\"quick\"><div class=\"kh-section-head\"><div class=\"kh-section-title\"><span class=\"kh-quick-heading-icon\" aria-hidden=\"true\">⚡</span><span>Hızlı İşlemler</span></div></div><div class=\"kh-quick\"><button type=\"button\" data-dash-route=\"academic\" data-dash-page=\"written\" data-dash-title=\"Yazılı Sınavlar\">${exam}<b>Sınav Ekle</b></button><button type=\"button\" data-dash-quick-note>${note}<b>Not Ekle</b></button><button type=\"button\" data-dash-route=\"communication\" data-dash-page=\"messages\" data-dash-title=\"Mesajlaşma\">${message}<b>Mesaj Gönder</b></button><button type=\"button\" data-dash-route=\"communication\" data-dash-page=\"announcements\" data-dash-title=\"Duyurular\">${megaphone}<b>Duyurular</b></button></div></section>`}"""
if old not in dash:
    raise SystemExit('quickSection source pattern not found')
dash=dash.replace(old,new,1)
DASH.write_text(dash,encoding='utf-8')

css=CSS.read_text(encoding='utf-8')
marker='/* LEGACY QUICK ACTIONS — REFERENCE PORT */'
block='''\n\n/* LEGACY QUICK ACTIONS — REFERENCE PORT */\n.ka-home .kh-section[data-home-section="quick"]{display:flex;flex-direction:column;gap:8px}\n.ka-home .kh-section[data-home-section="quick"] .kh-section-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 2px}\n.ka-home .kh-section[data-home-section="quick"] .kh-section-title{display:flex;align-items:center;gap:8px;min-width:0;font-size:15.5px;font-weight:900;color:var(--ka-text)}\n.ka-home .kh-quick-heading-icon{width:19px;height:19px;display:grid;place-items:center;color:var(--ka-primary);font-size:16px}\n.ka-home .kh-quick{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}\n.ka-home .kh-quick button{min-width:0;min-height:82px;border:1px solid var(--ka-border);border-radius:18px;background:var(--ka-card-bg);box-shadow:var(--ka-shadow-sm);color:var(--ka-text);font:inherit;font-size:9.5px;font-weight:800;padding:8px 3px;cursor:pointer;transition:transform var(--ka-transition-fast),border-color var(--ka-transition-fast),background var(--ka-transition-fast)}\n.ka-home .kh-quick button:active{transform:translateY(1px)}\n.ka-home .kh-quick button:focus-visible{outline:3px solid var(--ka-focus);outline-offset:2px}\n.ka-home .kh-quick button svg{width:23px;height:23px;display:block;margin:0 auto 7px;color:var(--ka-primary)}\n.ka-home .kh-quick button b{display:block;font-size:9.5px;line-height:1.25;font-weight:800}\n.ka-home .kh-quick button:nth-child(1){background:linear-gradient(180deg,var(--ka-card-bg),color-mix(in srgb,var(--ka-danger) 7%,var(--ka-card-bg)))}\n.ka-home .kh-quick button:nth-child(2){background:linear-gradient(180deg,var(--ka-card-bg),color-mix(in srgb,var(--ka-warning) 8%,var(--ka-card-bg)))}\n.ka-home .kh-quick button:nth-child(3){background:linear-gradient(180deg,var(--ka-card-bg),color-mix(in srgb,var(--ka-info) 8%,var(--ka-card-bg)))}\n.ka-home .kh-quick button:nth-child(4){background:linear-gradient(180deg,var(--ka-card-bg),var(--ka-primary-soft))}\n.ka-home .kh-quick button:nth-child(1) svg{color:var(--ka-danger)}\n.ka-home .kh-quick button:nth-child(2) svg{color:var(--ka-warning)}\n.ka-home .kh-quick button:nth-child(3) svg{color:var(--ka-info)}\n.ka-home .kh-quick button:nth-child(4) svg{color:var(--ka-primary)}\n@media(max-width:380px){.ka-home .kh-quick{gap:6px}.ka-home .kh-quick button{min-height:76px;font-size:8.8px;padding-inline:2px}.ka-home .kh-quick button b{font-size:8.8px}}\n'''
if marker not in css:
    css+=block
CSS.write_text(css,encoding='utf-8')

test=TEST.read_text(encoding='utf-8')
check="""\nassert(dash.includes('class=\"kh-quick\"')&&dash.includes('data-home-section=\"quick\"'),'Hızlı İşlemler referans kh-quick DOM sözleşmesini kullanmalı.');\nassert(!dash.includes('class=\"ka-home-quick\"'),'Yeni taklit ka-home-quick renderer içinde kalmamalı.');\nassert(css.includes('LEGACY QUICK ACTIONS — REFERENCE PORT')&&css.includes('.ka-home .kh-quick button{'),'Hızlı İşlemler legacy geometrisi merkezi design-system içinde kalmalı.');\nassert(css.includes('background:var(--ka-card-bg)')&&css.includes('color:var(--ka-text)')&&css.includes('var(--ka-primary-soft)'),'Hızlı İşlemler renkleri merkezi --ka-* tema tokenlarından gelmeli.');\n// Checkpoint: legacy quick actions visual port.\n"""
if 'LEGACY QUICK ACTIONS — REFERENCE PORT' not in test:
    test+=check
TEST.write_text(test,encoding='utf-8')

sw=SW.read_text(encoding='utf-8')
sw=sw.replace("const CACHE_ADI='oy-cache-v714';","const CACHE_ADI='oy-cache-v715';")
SW.write_text(sw,encoding='utf-8')
